using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class ServiceAuditUiTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{true,false})using(var form=new ServiceProbeForm("Audit preview",true)){form.SetTheme(dark,false);form.Show();for(int i=0;i<10;i++)Application.DoEvents();var controls=Walk(form).ToArray();if(controls.OfType<ComboBox>().Any())throw new Exception("Unexpected dropdown");n++;var buttons=controls.OfType<BrandButton>().Where(b=>new[]{"Проверить отклик","Открыть Swagger","Назад"}.Contains(b.Text)).ToArray();foreach(var button in buttons)Console.WriteLine(button.Text+" "+button.Size);if(buttons.Length!=3||buttons.Max(b=>b.Width)-buttons.Min(b=>b.Width)>1||buttons.Select(b=>b.Height).Distinct().Count()!=1)throw new Exception("Unequal actions");n++;var address=controls.OfType<BrandTextBox>().Single();var toggle=controls.OfType<RefreshToggle>().Single();Control card=controls.OfType<JournalTextBox>().Single().Parent;while(!(card is Card))card=card.Parent;var bounds=address.RectangleToScreen(address.ClientRectangle);var cardBounds=card.RectangleToScreen(card.ClientRectangle);if(address.ReadOnly||Math.Abs(address.Parent.PointToScreen(address.Location).X-(cardBounds.Left+1))>1||Math.Abs(address.Parent.PointToScreen(new Point(address.Right,0)).X-(cardBounds.Right-1))>1)throw new Exception("Address editability/card edges "+address.Bounds+" "+cardBounds+" parent="+card.GetType().Name+" left="+address.PointToScreen(Point.Empty));n++;if(Math.Abs(toggle.PointToScreen(new Point(toggle.Width,0)).X-(cardBounds.Right-1))>1)throw new Exception("Toggle right edge");n++;address.Text="tcp://127.0.0.1:36513/";if(!buttons.Single(b=>b.Text=="Проверить отклик").Enabled)throw new Exception("Manual address must enable check");address.Clear();if(buttons.Single(b=>b.Text=="Проверить отклик").Enabled)throw new Exception("Empty address must disable check");n++;using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"service-probe-"+dark+".png"));}}Console.WriteLine("PASS: "+n+" UI checks, preview only.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}